def grade_equation(gpas, letter_grades=None):
    """
    Convert a list of GPAs to letter grades.

    Rules:
      - Exactly 4.0 -> 'A+'
      - Otherwise use strict greater-than checks down the table:
        > 3.7 A, > 3.3 A-, > 3.0 B+, > 2.7 B, > 2.3 B-, > 2.0 C+,
        > 1.7 C, > 1.3 C-, > 1.0 D+, > 0.7 D, > 0.0 D-
      - Anything else (e.g., 0.0 or below) -> 'E'
    """
    result = []
    for gpa in gpas:
        if gpa == 4.0:
            result.append('A+')
        elif gpa > 3.7:
            result.append('A')
        elif gpa > 3.3:
            result.append('A-')
        elif gpa > 3.0:
            result.append('B+')
        elif gpa > 2.7:
            result.append('B')
        elif gpa > 2.3:
            result.append('B-')
        elif gpa > 2.0:
            result.append('C+')
        elif gpa > 1.7:
            result.append('C')
        elif gpa > 1.3:
            result.append('C-')
        elif gpa > 1.0:
            result.append('D+')
        elif gpa > 0.7:
            result.append('D')
        elif gpa > 0.0:
            result.append('D-')
        else:
            result.append('E')
    return result


# Example:
print(grade_equation([4.0, 3, 1.7, 0.0]))
# Output: ['A+', 'B+', 'C', 'E']
